#!/usr/bin/env python3
"""Extract verifiable evidence for the gate-level prerequisite question.

Read-only: loads the authoritative map and the approved relation file, computes
the prerequisite expression for KU-044, and writes evidence.json.
"""
import hashlib
import json
from collections import defaultdict
from datetime import datetime, timezone
from pathlib import Path

HERE = Path(__file__).resolve()
ROOT = next(p for p in HERE.parents if (p / "期中/数据/知识地图.json").exists())
MAP = ROOT / "期中/数据/知识地图.json"
REL = ROOT / "期中/待审查/07-价值关系.json"
OUT = HERE.parent / "evidence.json"


def sha256(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()


def unit_brief(store, uid):
    u = store["units"][uid]
    return {
        "id": uid,
        "name": u["name"],
        "themeId": u["themeId"],
        "themeName": store["themes"][u["themeId"]]["name"],
        "kind": u["kind"],
        "outcome": u["outcome"],
        "summary": u["summary"],
        "stars": u["rating"]["stars"],
        "ratingRationale": u["rating"]["rationale"],
        "sourceRefs": u["sourceRefs"],
    }


data = json.loads(MAP.read_text(encoding="utf-8"))
approved = json.loads(REL.read_text(encoding="utf-8"))
store = {
    "units": {u["id"]: u for u in data["units"]},
    "themes": {t["id"]: t for t in data["themes"]},
    "questions": {q["id"]: q for q in data["questions"]},
    "relations": {r["id"]: r for r in data["relations"]},
    "mappings": data["mappings"],
}

focus = ["KU-044", "KU-033", "KU-035", "KU-029", "KU-023", "KU-034", "KU-028"]
incoming = defaultdict(list)
outgoing = defaultdict(list)
for r in data["relations"]:
    if r["type"] == "requires":
        incoming[r["toUnitId"]].append(r)
        outgoing[r["fromUnitId"]].append(r)

direct_incoming = {}
for uid in focus:
    direct_incoming[uid] = {
        "andRequired": [r["fromUnitId"] for r in incoming[uid] if not r.get("requirementGroupId")],
        "groups": [
            {
                "groupId": r["requirementGroupId"],
                "from": r["fromUnitId"],
                "relationId": r["id"],
            }
            for r in incoming[uid]
            if r.get("requirementGroupId")
        ],
        "incomingRelations": [r["id"] for r in incoming[uid]],
        "outgoingRequires": [r["toUnitId"] for r in outgoing[uid]],
    }

g1 = next(g for g in data["requirementGroups"] if g["id"] == "G1")
g1_approved = next(g for g in approved["requirementGroups"] if g["id"] == "G1")

# Every target that has the two simplification units as direct prerequisites.
both_targets = []
any_targets = []
for tgt, rels in incoming.items():
    plain = {r["fromUnitId"] for r in rels if not r.get("requirementGroupId")}
    grouped = defaultdict(set)
    for r in rels:
        if r.get("requirementGroupId"):
            grouped[r["requirementGroupId"]].add(r["fromUnitId"])
    if {"KU-033", "KU-035"} <= plain:
        both_targets.append(tgt)
    for gid, members in grouped.items():
        if {"KU-033", "KU-035"} <= members:
            any_targets.append({"target": tgt, "groupId": gid})

# Question evidence for the three units.
question_evidence = {}
for uid in ["KU-044", "KU-033", "KU-035"]:
    items = []
    for m in data["mappings"]:
        if m["unitId"] == uid:
            q = store["questions"][m["questionId"]]
            items.append({
                "questionId": q["id"],
                "label": q["label"],
                "sourceId": q["sourceId"],
                "kind": q["kind"],
                "taskSummary": q["taskSummary"],
                "role": m["role"],
                "basis": m["basis"],
                "note": m["note"],
            })
    question_evidence[uid] = {
        "count": len(items),
        "direct": sum(1 for x in items if x["role"] == "direct"),
        "support": sum(1 for x in items if x["role"] == "support"),
        "items": items,
    }

overlap_questions = sorted(
    {m["questionId"] for m in data["mappings"] if m["unitId"] == "KU-033"}
    & {m["questionId"] for m in data["mappings"] if m["unitId"] == "KU-035"}
)
overlap = []
for qid in overlap_questions:
    q = store["questions"][qid]
    overlap.append({
        "questionId": qid,
        "label": q["label"],
        "taskSummary": q["taskSummary"],
        "notes": {
            m["unitId"]: m["note"]
            for m in data["mappings"]
            if m["questionId"] == qid and m["unitId"] in {"KU-033", "KU-035"}
        },
    })

# Cross-file consistency between authoritative data and the approved 07 file.
relations_authoritative = {r["id"]: r for r in data["relations"]}
relations_seven = {r["id"]: r for r in approved["relations"]}
consistent = {
    "sameRelationIds": sorted(relations_authoritative) == sorted(relations_seven),
    "relationsOnlyInMap": sorted(set(relations_authoritative) - set(relations_seven)),
    "relationsOnlyIn07": sorted(set(relations_seven) - set(relations_authoritative)),
    "relationPayloadEqual": all(
        relations_authoritative[rid] == relations_seven[rid]
        for rid in relations_authoritative
        if rid in relations_seven
    ),
    "G1Equal": g1 == g1_approved,
    "rejectedCandidates": approved["rejectedCandidates"],
}

result = {
    "meta": {
        "generatedAt": datetime.now(timezone.utc).isoformat(),
        "projectRoot": str(ROOT),
        "authoritativeData": {
            "path": str(MAP.relative_to(ROOT)),
            "sha256": sha256(MAP),
            "schemaVersion": data["schemaVersion"],
            "status": data["status"],
        },
        "approvedRelations": {
            "path": str(REL.relative_to(ROOT)),
            "sha256": sha256(REL),
            "status": approved["status"],
        },
        "method": "Read-only JSON extraction plus Store CLI queries; no data or tool files modified.",
    },
    "question": "门级电路实现是否必须同时掌握代数化简和卡诺图？",
    "referent": {
        "note": "权威数据没有名为“门级电路实现”的单元；通用门级设计对应 KU-044 组合逻辑设计流程（outcome 含“画电路并验证”）。KU-020/KU-031 是门构造单元，但无任何前置关系。",
        "target": unit_brief(store, "KU-044"),
    },
    "answer": {
        "mustMasterBoth": False,
        "mustMasterAtLeastOne": True,
        "reason": "G1 的 mode=any，KU-033 与 KU-035 是 KU-044 化简步骤的可替代路线；但 KU-044 仍要求“求输出函数的最简表达式”，所以不能两条都不掌握。",
        "booleanPrerequisiteExpression": "KU-044 <- KU-029 AND (KU-033 OR KU-035); KU-033 <- KU-023; KU-035 <- KU-034 <- KU-028",
    },
    "alternatives": [unit_brief(store, "KU-033"), unit_brief(store, "KU-035")],
    "commonRequired": unit_brief(store, "KU-029"),
    "routePrerequisites": {
        "KU-033": unit_brief(store, "KU-023"),
        "KU-035": unit_brief(store, "KU-034"),
        "KU-034": unit_brief(store, "KU-028"),
    },
    "requirementGroup": g1,
    "prerequisiteEdges": sorted(
        (
            {
                "id": r["id"],
                "from": r["fromUnitId"],
                "to": r["toUnitId"],
                "type": r["type"],
                "requirementGroupId": r.get("requirementGroupId"),
                "view": r["view"],
                "status": r["status"],
                "value": r["value"],
            }
            for r in data["relations"]
            if r["type"] == "requires"
            and ({r["fromUnitId"], r["toUnitId"]} & set(focus))
            and r["toUnitId"] in focus
        ),
        key=lambda x: x["id"],
    ),
    "directIncomingByUnit": direct_incoming,
    "graphChecks": {
        "targetsRequiringBothKU033AndKU035InAnd": both_targets,
        "targetsWithAnyGroupContainingBoth": any_targets,
        "directRelationBetweenKU033AndKU035": [
            r["id"]
            for r in data["relations"]
            if {r["fromUnitId"], r["toUnitId"]} == {"KU-033", "KU-035"}
        ],
        "inverseRelationIntoKU044": [
            {
                "id": r["id"],
                "type": r["type"],
                "from": r["fromUnitId"],
                "to": r["toUnitId"],
                "view": r["view"],
                "value": r["value"],
            }
            for r in data["relations"]
            if r["toUnitId"] == "KU-044" and r["type"] != "requires"
        ],
        "otherGateConstructionUnits": {
            uid: {
                "name": store["units"][uid]["name"],
                "incomingRequires": [r["id"] for r in incoming[uid]],
            }
            for uid in ["KU-020", "KU-031"]
        },
    },
    "questionEvidence": {
        "byUnit": question_evidence,
        "questionsMappedToBothKU033AndKU035": overlap,
    },
    "crossFileConsistency": consistent,
    "implications": {
        "notBoth": [
            "G1.mode = any",
            "REL-010 and REL-011 both carry requirementGroupId G1",
            "07 rejected KU-033 <-> KU-035 requires/improves: no general order or superiority",
        ],
        "notNeither": [
            "KU-044 outcome and courseware C04 p20 step 3 require a minimal expression",
            "KU-029 is a separate AND prerequisite for truth-table/standard-form conversion",
        ],
        "coverageCaveat": "Both KU-033 and KU-035 are 5-star and directly examined; some specific tasks prescribe one method, so exam coverage still favors learning both even though the design flow does not require both.",
    },
}

OUT.write_text(json.dumps(result, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
print(f"wrote {OUT}")
print(f"mustMasterBoth={result['answer']['mustMasterBoth']} "
      f"targetsRequiringBoth={both_targets} "
      f"consistency={consistent['sameRelationIds'] and consistent['relationPayloadEqual'] and consistent['G1Equal']}")

